export type LogoLockup = 'horizontal' | 'stacked' | 'wordmark' | 'mark'
export type LogoVariant = 'on-light' | 'on-navy' | 'navy' | 'white'

/** File sizes are not recorded here: the hub reads them from the asset manifest (kit:zips), which sees the final files. */
export interface AssetFile {
  /** Public URL path. */
  url: string
}

export interface LogoPng extends AssetFile {
  scale: number
  width: number
  height: number
}

export interface LogoAsset {
  lockup: LogoLockup
  variant: LogoVariant
  /** The master layout: use this one unless space dictates otherwise. */
  primary: boolean
  lockupLabel: string
  label: string
  /** Token of the ground this variant is made for. */
  ground: '--paper' | '--navy'
  note: string
  svg: AssetFile & { width: number; height: number }
  pngs: LogoPng[]
}

export interface AppTile {
  id: string
  label: string
  note: string
  svg: AssetFile & { width: number; height: number }
  pngs: LogoPng[]
}

export interface IconFile extends AssetFile {
  kind: string
  width: number | null
  height: number | null
}

